import{_ as n,c as a,o as i,a2 as o}from"./chunks/framework.B7el9cAC.js";const u=JSON.parse('{"title":"Mục 2.4 – Mô Hình OSI","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-2/2.4-mo-hinh-osi.md","filePath":"chuong-2/2.4-mo-hinh-osi.md","lastUpdated":1775298873000}'),h={name:"chuong-2/2.4-mo-hinh-osi.md"};function g(r,t,s,e,d,l){return i(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="muc-2-4-–-mo-hinh-osi" tabindex="-1">Mục 2.4 – Mô Hình OSI <a class="header-anchor" href="#muc-2-4-–-mo-hinh-osi" aria-label="Permalink to &quot;Mục 2.4 – Mô Hình OSI&quot;">​</a></h1><blockquote><p><strong>Chương 2: Mạng máy tính và Internet</strong></p></blockquote><hr><h2 id="🔹-1-gioi-thieu-sieu-co-ban" tabindex="-1">🔹 1. GIỚI THIỆU SIÊU CƠ BẢN <a class="header-anchor" href="#🔹-1-gioi-thieu-sieu-co-ban" aria-label="Permalink to &quot;🔹 1. GIỚI THIỆU SIÊU CƠ BẢN&quot;">​</a></h2><h3 id="tai-sao-can-mo-hinh-osi" tabindex="-1">Tại sao cần mô hình OSI? <a class="header-anchor" href="#tai-sao-can-mo-hinh-osi" aria-label="Permalink to &quot;Tại sao cần mô hình OSI?&quot;">​</a></h3><p>Hãy tưởng tượng bạn gửi một bức thư quốc tế: Bạn viết thư → bỏ vào phong bì → ghi địa chỉ → đưa cho bưu điện → xe chở đến sân bay → máy bay chở sang nước khác → xe chở đến bưu cục → người đưa thư mang đến nhà → người nhận bóc thư ra đọc. Mỗi bước là một <strong>khâu riêng biệt</strong>, có vai trò riêng, không cần biết các khâu khác làm gì.</p><p><strong>Mô hình OSI</strong> cũng hoạt động tương tự: khi bạn gửi dữ liệu qua mạng, dữ liệu đó đi qua <strong>7 tầng (layer)</strong> khác nhau, mỗi tầng xử lý một phần việc cụ thể.</p><p><strong>Tại sao quan trọng?</strong></p><ul><li>Trước OSI, mỗi hãng máy tính (IBM, DEC, HP...) tạo ra giao thức mạng riêng, các hãng khác không thể kết nối được.</li><li>OSI ra đời năm 1984 (do ISO ban hành) để <strong>chuẩn hóa</strong> cách các hệ thống mạng khác nhau giao tiếp với nhau.</li><li>Dù TCP/IP được dùng thực tế nhiều hơn, OSI vẫn là <strong>nền tảng lý thuyết</strong> để hiểu mạng máy tính.</li></ul><hr><h2 id="🔹-2-ly-thuyet-chi-tiet" tabindex="-1">🔹 2. LÝ THUYẾT CHI TIẾT <a class="header-anchor" href="#🔹-2-ly-thuyet-chi-tiet" aria-label="Permalink to &quot;🔹 2. LÝ THUYẾT CHI TIẾT&quot;">​</a></h2><h3 id="_2-1-mo-hinh-osi-la-gi" tabindex="-1">2.1 Mô hình OSI là gì? <a class="header-anchor" href="#_2-1-mo-hinh-osi-la-gi" aria-label="Permalink to &quot;2.1 Mô hình OSI là gì?&quot;">​</a></h3><p><strong>OSI (Open Systems Interconnection)</strong> là mô hình tham chiếu 7 tầng, mô tả cách dữ liệu được truyền từ ứng dụng của máy tính này sang ứng dụng của máy tính khác qua mạng.</p><blockquote><p>&quot;Open Systems&quot; = Hệ thống mở – nghĩa là bất kỳ thiết bị nào cũng có thể giao tiếp với nhau nếu tuân theo chuẩn.</p></blockquote><h3 id="_2-2-bay-tang-cua-mo-hinh-osi" tabindex="-1">2.2 Bảy tầng của mô hình OSI <a class="header-anchor" href="#_2-2-bay-tang-cua-mo-hinh-osi" aria-label="Permalink to &quot;2.2 Bảy tầng của mô hình OSI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Số tầng</th><th>Tên tầng</th><th>Tên tiếng Việt</th><th>Chức năng chính</th></tr></thead><tbody><tr><td><strong>7</strong></td><td>Application</td><td>Tầng Ứng dụng</td><td>Giao tiếp với phần mềm người dùng</td></tr><tr><td><strong>6</strong></td><td>Presentation</td><td>Tầng Trình bày</td><td>Mã hóa, nén, chuyển đổi định dạng</td></tr><tr><td><strong>5</strong></td><td>Session</td><td>Tầng Phiên</td><td>Thiết lập, quản lý, kết thúc phiên làm việc</td></tr><tr><td><strong>4</strong></td><td>Transport</td><td>Tầng Vận chuyển</td><td>Phân mảnh, TCP/UDP, kiểm soát lỗi</td></tr><tr><td><strong>3</strong></td><td>Network</td><td>Tầng Mạng</td><td>Địa chỉ IP, định tuyến</td></tr><tr><td><strong>2</strong></td><td>Data Link</td><td>Tầng Liên kết dữ liệu</td><td>Địa chỉ MAC, phát hiện lỗi vật lý</td></tr><tr><td><strong>1</strong></td><td>Physical</td><td>Tầng Vật lý</td><td>Truyền bit qua cáp, sóng vô tuyến</td></tr></tbody></table><blockquote><p><strong>Mẹo nhớ (từ trên xuống):</strong> &quot;<strong>A</strong>ll <strong>P</strong>eople <strong>S</strong>eem <strong>T</strong>o <strong>N</strong>eed <strong>D</strong>ata <strong>P</strong>rocessing&quot; → Application, Presentation, Session, Transport, Network, Data Link, Physical</p></blockquote><h3 id="_2-3-chi-tiet-tung-tang" tabindex="-1">2.3 Chi tiết từng tầng <a class="header-anchor" href="#_2-3-chi-tiet-tung-tang" aria-label="Permalink to &quot;2.3 Chi tiết từng tầng&quot;">​</a></h3><h4 id="🔵-tang-7-–-application-ung-dung" tabindex="-1">🔵 Tầng 7 – Application (Ứng dụng) <a class="header-anchor" href="#🔵-tang-7-–-application-ung-dung" aria-label="Permalink to &quot;🔵 Tầng 7 – Application (Ứng dụng)&quot;">​</a></h4><ul><li><strong>Chức năng:</strong> Cung cấp giao diện giữa ứng dụng và mạng.</li><li><strong>Đây là tầng duy nhất người dùng tương tác trực tiếp</strong>.</li><li>Không phải là phần mềm ứng dụng (như Chrome hay Word), mà là giao thức ứng dụng.</li><li><strong>Giao thức:</strong> HTTP/HTTPS (web), SMTP/POP3/IMAP (email), FTP (truyền file), DNS (phân giải tên miền).</li><li><strong>Đơn vị dữ liệu:</strong> Data (dữ liệu).</li></ul><h4 id="🟢-tang-6-–-presentation-trinh-bay" tabindex="-1">🟢 Tầng 6 – Presentation (Trình bày) <a class="header-anchor" href="#🟢-tang-6-–-presentation-trinh-bay" aria-label="Permalink to &quot;🟢 Tầng 6 – Presentation (Trình bày)&quot;">​</a></h4><ul><li><strong>Chức năng:</strong> Chuyển đổi, mã hóa, nén dữ liệu để tầng Application có thể đọc được.</li><li><strong>Ví dụ:</strong><ul><li>Mã hóa SSL/TLS (khi bạn truy cập website HTTPS).</li><li>Nén dữ liệu (ZIP, JPEG, MP3).</li><li>Chuyển đổi định dạng ký tự (ASCII sang Unicode).</li></ul></li><li><strong>Đơn vị dữ liệu:</strong> Data.</li></ul><h4 id="🟡-tang-5-–-session-phien" tabindex="-1">🟡 Tầng 5 – Session (Phiên) <a class="header-anchor" href="#🟡-tang-5-–-session-phien" aria-label="Permalink to &quot;🟡 Tầng 5 – Session (Phiên)&quot;">​</a></h4><ul><li><strong>Chức năng:</strong> Thiết lập, duy trì, và kết thúc &quot;phiên&quot; (session) giao tiếp giữa hai máy.</li><li><strong>Ví dụ:</strong><ul><li>Khi bạn đăng nhập vào Facebook, tầng Session duy trì phiên đăng nhập đó cho đến khi bạn đăng xuất.</li><li>Khi mạng bị ngắt giữa chừng trong khi tải file, tầng Session cho phép <strong>tiếp tục</strong> từ điểm bị ngắt (resume).</li></ul></li><li><strong>Đơn vị dữ liệu:</strong> Data.</li></ul><h4 id="🔴-tang-4-–-transport-van-chuyen" tabindex="-1">🔴 Tầng 4 – Transport (Vận chuyển) <a class="header-anchor" href="#🔴-tang-4-–-transport-van-chuyen" aria-label="Permalink to &quot;🔴 Tầng 4 – Transport (Vận chuyển)&quot;">​</a></h4><ul><li><strong>Chức năng:</strong> Truyền dữ liệu đáng tin cậy từ đầu cuối đến đầu cuối (end-to-end).</li><li>Chia dữ liệu thành các <strong>segment</strong> (TCP) hoặc <strong>datagram</strong> (UDP).</li><li>Đánh số thứ tự, xác nhận (ACK), gửi lại nếu mất (TCP).</li><li><strong>Giao thức:</strong> TCP (tin cậy, chậm hơn), UDP (nhanh, không tin cậy).</li><li>Dùng <strong>số cổng (port)</strong> để phân biệt ứng dụng: HTTP=80, HTTPS=443, SMTP=25, FTP=21.</li><li><strong>Đơn vị dữ liệu:</strong> Segment (TCP) / Datagram (UDP).</li></ul><h4 id="🟠-tang-3-–-network-mang" tabindex="-1">🟠 Tầng 3 – Network (Mạng) <a class="header-anchor" href="#🟠-tang-3-–-network-mang" aria-label="Permalink to &quot;🟠 Tầng 3 – Network (Mạng)&quot;">​</a></h4><ul><li><strong>Chức năng:</strong> Định tuyến gói tin từ nguồn đến đích qua nhiều mạng trung gian.</li><li>Dùng <strong>địa chỉ IP</strong> (logic) để nhận diện thiết bị.</li><li>Thiết bị hoạt động ở tầng này: <strong>Router</strong>.</li><li><strong>Giao thức:</strong> IP, ICMP (ping), ARP.</li><li><strong>Đơn vị dữ liệu:</strong> Packet (gói tin).</li></ul><h4 id="🟤-tang-2-–-data-link-lien-ket-du-lieu" tabindex="-1">🟤 Tầng 2 – Data Link (Liên kết dữ liệu) <a class="header-anchor" href="#🟤-tang-2-–-data-link-lien-ket-du-lieu" aria-label="Permalink to &quot;🟤 Tầng 2 – Data Link (Liên kết dữ liệu)&quot;">​</a></h4><ul><li><strong>Chức năng:</strong> Truyền dữ liệu tin cậy giữa hai node kết nối trực tiếp, phát hiện lỗi vật lý.</li><li>Dùng <strong>địa chỉ MAC</strong> để nhận diện thiết bị trong cùng mạng.</li><li>Thiết bị hoạt động ở tầng này: <strong>Switch</strong>, Bridge.</li><li>Chia thành 2 lớp con: <ul><li><strong>LLC (Logical Link Control):</strong> Kiểm soát luồng.</li><li><strong>MAC (Media Access Control):</strong> Địa chỉ vật lý, điều khiển truy cập.</li></ul></li><li><strong>Đơn vị dữ liệu:</strong> Frame (khung).</li></ul><h4 id="⚫-tang-1-–-physical-vat-ly" tabindex="-1">⚫ Tầng 1 – Physical (Vật lý) <a class="header-anchor" href="#⚫-tang-1-–-physical-vat-ly" aria-label="Permalink to &quot;⚫ Tầng 1 – Physical (Vật lý)&quot;">​</a></h4><ul><li><strong>Chức năng:</strong> Truyền các bit (0 và 1) dưới dạng tín hiệu điện, tín hiệu quang, hoặc sóng vô tuyến qua môi trường truyền dẫn.</li><li>Quy định: điện áp, tần số sóng, loại đầu cắm, loại cáp.</li><li>Thiết bị: Hub, Repeater, cáp Ethernet, cáp quang, anten Wi-Fi.</li><li><strong>Đơn vị dữ liệu:</strong> Bit.</li></ul><hr><h2 id="🔹-3-giai-thich-ban-chat" tabindex="-1">🔹 3. GIẢI THÍCH BẢN CHẤT <a class="header-anchor" href="#🔹-3-giai-thich-ban-chat" aria-label="Permalink to &quot;🔹 3. GIẢI THÍCH BẢN CHẤT&quot;">​</a></h2><h3 id="qua-trinh-đong-goi-du-lieu-encapsulation" tabindex="-1">Quá trình đóng gói dữ liệu (Encapsulation) <a class="header-anchor" href="#qua-trinh-đong-goi-du-lieu-encapsulation" aria-label="Permalink to &quot;Quá trình đóng gói dữ liệu (Encapsulation)&quot;">​</a></h3><p>Khi gửi dữ liệu, dữ liệu đi <strong>từ tầng 7 xuống tầng 1</strong>, mỗi tầng <strong>thêm vào một &quot;tiêu đề&quot; (header)</strong> của tầng đó:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Tầng 7] Data</span></span>
<span class="line"><span>[Tầng 6] Data</span></span>
<span class="line"><span>[Tầng 5] Data</span></span>
<span class="line"><span>[Tầng 4] TCP Header | Data                        ← Segment</span></span>
<span class="line"><span>[Tầng 3] IP Header | TCP Header | Data            ← Packet</span></span>
<span class="line"><span>[Tầng 2] MAC Header | IP Header | TCP Header | Data | MAC Trailer  ← Frame</span></span>
<span class="line"><span>[Tầng 1] 01001011010010110...                     ← Bits</span></span></code></pre></div><p>Khi nhận dữ liệu, dữ liệu đi <strong>từ tầng 1 lên tầng 7</strong>, mỗi tầng <strong>bóc ra một tiêu đề</strong> của tầng đó (De-encapsulation).</p><blockquote><p><strong>Hình dung:</strong> Giống như bọc quà nhiều lớp – người nhận phải bóc từng lớp từ ngoài vào trong để lấy món quà thực sự.</p></blockquote><h3 id="điem-quan-trong-can-nho" tabindex="-1">Điểm quan trọng cần nhớ <a class="header-anchor" href="#điem-quan-trong-can-nho" aria-label="Permalink to &quot;Điểm quan trọng cần nhớ&quot;">​</a></h3><ul><li>Tầng <strong>7,6,5</strong> → xử lý bởi phần mềm ứng dụng.</li><li>Tầng <strong>4</strong> → TCP/UDP – kiểm soát truyền tải.</li><li>Tầng <strong>3</strong> → IP – định tuyến, Router hoạt động ở đây.</li><li>Tầng <strong>2</strong> → MAC – trong LAN, Switch hoạt động ở đây.</li><li>Tầng <strong>1</strong> → Tín hiệu vật lý – cáp, sóng Wi-Fi.</li></ul><hr><h2 id="🔹-4-luong-hoat-đong-step-by-step" tabindex="-1">🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP <a class="header-anchor" href="#🔹-4-luong-hoat-đong-step-by-step" aria-label="Permalink to &quot;🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP&quot;">​</a></h2><h3 id="gui-email-luong-du-lieu-qua-7-tang-osi" tabindex="-1">Gửi email: luồng dữ liệu qua 7 tầng OSI <a class="header-anchor" href="#gui-email-luong-du-lieu-qua-7-tang-osi" aria-label="Permalink to &quot;Gửi email: luồng dữ liệu qua 7 tầng OSI&quot;">​</a></h3><p><strong>Tình huống:</strong> Bạn gửi email từ máy tính của mình đến bạn bè ở thành phố khác.</p><p><strong>Phía người gửi (xuống từ tầng 7 → 1):</strong></p><table tabindex="0"><thead><tr><th>Tầng</th><th>Hành động</th></tr></thead><tbody><tr><td><strong>7 – Application</strong></td><td>Gmail tạo email (văn bản + file). Dùng giao thức SMTP.</td></tr><tr><td><strong>6 – Presentation</strong></td><td>Mã hóa nội dung email (TLS), chuyển sang định dạng MIME.</td></tr><tr><td><strong>5 – Session</strong></td><td>Mở phiên kết nối với máy chủ Gmail.</td></tr><tr><td><strong>4 – Transport</strong></td><td>TCP chia email thành các segment, gắn port nguồn (ngẫu nhiên) và port đích (SMTP=25).</td></tr><tr><td><strong>3 – Network</strong></td><td>IP đóng gói segment thành packet, gắn IP nguồn và IP đích (máy chủ Gmail).</td></tr><tr><td><strong>2 – Data Link</strong></td><td>Gắn địa chỉ MAC nguồn và MAC đích (router/gateway). Tạo Frame.</td></tr><tr><td><strong>1 – Physical</strong></td><td>Chuyển frame thành tín hiệu điện/quang và truyền qua cáp.</td></tr></tbody></table><p><strong>Phía người nhận (lên từ tầng 1 → 7) – ngược lại hoàn toàn.</strong></p><hr><h2 id="🔹-5-vi-du-minh-hoa" tabindex="-1">🔹 5. VÍ DỤ MINH HỌA <a class="header-anchor" href="#🔹-5-vi-du-minh-hoa" aria-label="Permalink to &quot;🔹 5. VÍ DỤ MINH HỌA&quot;">​</a></h2><h3 id="vi-du-1-–-co-ban-nhan-dien-tang-osi-tu-thiet-bi" tabindex="-1">Ví dụ 1 – Cơ bản: Nhận diện tầng OSI từ thiết bị <a class="header-anchor" href="#vi-du-1-–-co-ban-nhan-dien-tang-osi-tu-thiet-bi" aria-label="Permalink to &quot;Ví dụ 1 – Cơ bản: Nhận diện tầng OSI từ thiết bị&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Thiết bị</th><th>Tầng OSI</th><th>Giải thích</th></tr></thead><tbody><tr><td>Hub</td><td>Tầng 1 (Physical)</td><td>Chỉ khuếch đại tín hiệu, không đọc địa chỉ</td></tr><tr><td>Switch</td><td>Tầng 2 (Data Link)</td><td>Đọc địa chỉ MAC để chuyển frame</td></tr><tr><td>Router</td><td>Tầng 3 (Network)</td><td>Đọc địa chỉ IP để định tuyến packet</td></tr><tr><td>Firewall</td><td>Tầng 3-7</td><td>Lọc dựa trên IP, port, nội dung</td></tr><tr><td>Trình duyệt web</td><td>Tầng 7 (Application)</td><td>Dùng HTTP/HTTPS</td></tr></tbody></table><h3 id="vi-du-2-–-thuc-te-xac-đinh-tang-osi-tu-giao-thuc" tabindex="-1">Ví dụ 2 – Thực tế: Xác định tầng OSI từ giao thức <a class="header-anchor" href="#vi-du-2-–-thuc-te-xac-đinh-tang-osi-tu-giao-thuc" aria-label="Permalink to &quot;Ví dụ 2 – Thực tế: Xác định tầng OSI từ giao thức&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Giao thức</th><th>Tầng OSI</th><th>Ứng dụng</th></tr></thead><tbody><tr><td>HTTP/HTTPS</td><td>Tầng 7</td><td>Truy cập web</td></tr><tr><td>SMTP/POP3/IMAP</td><td>Tầng 7</td><td>Email</td></tr><tr><td>FTP</td><td>Tầng 7</td><td>Truyền file</td></tr><tr><td>DNS</td><td>Tầng 7</td><td>Phân giải tên miền</td></tr><tr><td>SSL/TLS</td><td>Tầng 6</td><td>Mã hóa dữ liệu</td></tr><tr><td>TCP</td><td>Tầng 4</td><td>Truyền tin cậy</td></tr><tr><td>UDP</td><td>Tầng 4</td><td>Truyền nhanh</td></tr><tr><td>IP</td><td>Tầng 3</td><td>Định tuyến</td></tr><tr><td>Ethernet</td><td>Tầng 2</td><td>Mạng LAN có dây</td></tr><tr><td>Wi-Fi (802.11)</td><td>Tầng 2</td><td>Mạng không dây</td></tr></tbody></table><h3 id="vi-du-3-–-nang-cao-so-sanh-osi-va-tcp-ip" tabindex="-1">Ví dụ 3 – Nâng cao: So sánh OSI và TCP/IP <a class="header-anchor" href="#vi-du-3-–-nang-cao-so-sanh-osi-va-tcp-ip" aria-label="Permalink to &quot;Ví dụ 3 – Nâng cao: So sánh OSI và TCP/IP&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Mô hình OSI              Mô hình TCP/IP</span></span>
<span class="line"><span>─────────────────        ─────────────────────</span></span>
<span class="line"><span>7. Application  ┐</span></span>
<span class="line"><span>6. Presentation ├──────► Application (HTTP, FTP, SMTP...)</span></span>
<span class="line"><span>5. Session      ┘</span></span>
<span class="line"><span>─────────────────        ─────────────────────</span></span>
<span class="line"><span>4. Transport    ───────► Transport (TCP, UDP)</span></span>
<span class="line"><span>─────────────────        ─────────────────────</span></span>
<span class="line"><span>3. Network      ───────► Internet (IP, ICMP, ARP)</span></span>
<span class="line"><span>─────────────────        ─────────────────────</span></span>
<span class="line"><span>2. Data Link    ┐</span></span>
<span class="line"><span>1. Physical     ├──────► Network Access (Ethernet, Wi-Fi)</span></span>
<span class="line"><span>                ┘</span></span></code></pre></div><blockquote><p>Mô hình TCP/IP gộp tầng 7+6+5 thành <strong>Application</strong>, và gộp tầng 2+1 thành <strong>Network Access</strong>.</p></blockquote><hr><h2 id="🔹-6-so-sanh-phan-biet" tabindex="-1">🔹 6. SO SÁNH &amp; PHÂN BIỆT <a class="header-anchor" href="#🔹-6-so-sanh-phan-biet" aria-label="Permalink to &quot;🔹 6. SO SÁNH &amp; PHÂN BIỆT&quot;">​</a></h2><h3 id="osi-vs-tcp-ip" tabindex="-1">OSI vs TCP/IP <a class="header-anchor" href="#osi-vs-tcp-ip" aria-label="Permalink to &quot;OSI vs TCP/IP&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>OSI</th><th>TCP/IP</th></tr></thead><tbody><tr><td><strong>Số tầng</strong></td><td>7</td><td>4</td></tr><tr><td><strong>Mục đích</strong></td><td>Lý thuyết, tham chiếu</td><td>Thực tế, được dùng trên Internet</td></tr><tr><td><strong>Phát triển</strong></td><td>ISO (1984)</td><td>DoD/ARPANET (1970s)</td></tr><tr><td><strong>Ứng dụng</strong></td><td>Học tập, chuẩn hóa</td><td>Hoạt động thực tế của Internet</td></tr><tr><td><strong>Độ linh hoạt</strong></td><td>Cứng nhắc hơn</td><td>Linh hoạt hơn</td></tr></tbody></table><h3 id="đon-vi-du-lieu-o-tung-tang" tabindex="-1">Đơn vị dữ liệu ở từng tầng <a class="header-anchor" href="#đon-vi-du-lieu-o-tung-tang" aria-label="Permalink to &quot;Đơn vị dữ liệu ở từng tầng&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tầng</th><th>Tên đơn vị dữ liệu</th></tr></thead><tbody><tr><td>Tầng 7, 6, 5</td><td>Data (dữ liệu)</td></tr><tr><td>Tầng 4</td><td>Segment (TCP) / Datagram (UDP)</td></tr><tr><td>Tầng 3</td><td>Packet (gói tin)</td></tr><tr><td>Tầng 2</td><td>Frame (khung)</td></tr><tr><td>Tầng 1</td><td>Bit</td></tr></tbody></table><hr><h2 id="🔹-7-ghi-nho-nhanh-đi-thi" tabindex="-1">🔹 7. GHI NHỚ NHANH (ĐI THI) <a class="header-anchor" href="#🔹-7-ghi-nho-nhanh-đi-thi" aria-label="Permalink to &quot;🔹 7. GHI NHỚ NHANH (ĐI THI)&quot;">​</a></h2><ul><li>🏗️ OSI có <strong>7 tầng</strong> – từ trên xuống: <strong>Application → Physical</strong></li><li>🔑 Mẹo nhớ: <strong>&quot;All People Seem To Need Data Processing&quot;</strong></li><li>📱 Tầng <strong>7 (Application):</strong> HTTP, HTTPS, FTP, SMTP, DNS</li><li>🔐 Tầng <strong>6 (Presentation):</strong> Mã hóa SSL/TLS, nén ZIP/JPEG</li><li>🔗 Tầng <strong>5 (Session):</strong> Quản lý phiên đăng nhập</li><li>📦 Tầng <strong>4 (Transport):</strong> TCP/UDP, port, phân mảnh → đơn vị: <strong>Segment</strong></li><li>🌐 Tầng <strong>3 (Network):</strong> IP, Router, định tuyến → đơn vị: <strong>Packet</strong></li><li>🖥️ Tầng <strong>2 (Data Link):</strong> MAC, Switch, Ethernet → đơn vị: <strong>Frame</strong></li><li>⚡ Tầng <strong>1 (Physical):</strong> Cáp, sóng, Hub → đơn vị: <strong>Bit</strong></li><li>🔄 Gửi dữ liệu: đóng gói từ <strong>tầng 7 → 1</strong> (thêm header mỗi tầng)</li><li>🔄 Nhận dữ liệu: bóc gói từ <strong>tầng 1 → 7</strong> (bỏ header mỗi tầng)</li><li>🔵 <strong>Router</strong> ↔ Tầng 3 | <strong>Switch</strong> ↔ Tầng 2 | <strong>Hub</strong> ↔ Tầng 1</li></ul><hr><h2 id="🔹-8-bai-tap-tu-luyen" tabindex="-1">🔹 8. BÀI TẬP TỰ LUYỆN <a class="header-anchor" href="#🔹-8-bai-tap-tu-luyen" aria-label="Permalink to &quot;🔹 8. BÀI TẬP TỰ LUYỆN&quot;">​</a></h2><h3 id="cau-1-de-đien-vao-bang" tabindex="-1">Câu 1 (Dễ): Điền vào bảng <a class="header-anchor" href="#cau-1-de-đien-vao-bang" aria-label="Permalink to &quot;Câu 1 (Dễ): Điền vào bảng&quot;">​</a></h3><blockquote><p>Điền tên tầng OSI và đơn vị dữ liệu tương ứng vào bảng sau:</p></blockquote><table tabindex="0"><thead><tr><th>Số tầng</th><th>Tên tầng</th><th>Đơn vị dữ liệu</th></tr></thead><tbody><tr><td>7</td><td>?</td><td>?</td></tr><tr><td>4</td><td>?</td><td>?</td></tr><tr><td>3</td><td>?</td><td>?</td></tr><tr><td>2</td><td>?</td><td>?</td></tr><tr><td>1</td><td>?</td><td>?</td></tr></tbody></table><p><strong>Đáp án:</strong></p><table tabindex="0"><thead><tr><th>Số tầng</th><th>Tên tầng</th><th>Đơn vị dữ liệu</th></tr></thead><tbody><tr><td>7</td><td>Application</td><td>Data</td></tr><tr><td>4</td><td>Transport</td><td>Segment</td></tr><tr><td>3</td><td>Network</td><td>Packet</td></tr><tr><td>2</td><td>Data Link</td><td>Frame</td></tr><tr><td>1</td><td>Physical</td><td>Bit</td></tr></tbody></table><hr><h3 id="cau-2-de-trac-nghiem" tabindex="-1">Câu 2 (Dễ): Trắc nghiệm <a class="header-anchor" href="#cau-2-de-trac-nghiem" aria-label="Permalink to &quot;Câu 2 (Dễ): Trắc nghiệm&quot;">​</a></h3><blockquote><p>Thiết bị nào hoạt động ở Tầng 3 của mô hình OSI? A. Hub B. Switch C. Router D. Repeater</p></blockquote><p><strong>Đáp án: C – Router</strong></p><p><strong>Giải thích:</strong> Router hoạt động ở Tầng 3 (Network Layer), đọc địa chỉ IP để định tuyến packet qua các mạng khác nhau. Switch ở Tầng 2 (dùng MAC), Hub và Repeater ở Tầng 1 (chỉ khuếch đại tín hiệu).</p><hr><h3 id="cau-3-trung-binh-xac-đinh-tang-osi" tabindex="-1">Câu 3 (Trung bình): Xác định tầng OSI <a class="header-anchor" href="#cau-3-trung-binh-xac-đinh-tang-osi" aria-label="Permalink to &quot;Câu 3 (Trung bình): Xác định tầng OSI&quot;">​</a></h3><blockquote><p>Xác định tầng OSI tương ứng với mỗi giao thức/công nghệ sau: a) HTTP b) IP c) Ethernet d) TCP e) SSL/TLS</p></blockquote><p><strong>Đáp án:</strong></p><table tabindex="0"><thead><tr><th>Giao thức</th><th>Tầng OSI</th></tr></thead><tbody><tr><td>HTTP</td><td>Tầng 7 – Application</td></tr><tr><td>IP</td><td>Tầng 3 – Network</td></tr><tr><td>Ethernet</td><td>Tầng 2 – Data Link</td></tr><tr><td>TCP</td><td>Tầng 4 – Transport</td></tr><tr><td>SSL/TLS</td><td>Tầng 6 – Presentation</td></tr></tbody></table><hr><h3 id="cau-4-trung-binh-phan-tich-qua-trinh-gui-du-lieu" tabindex="-1">Câu 4 (Trung bình): Phân tích quá trình gửi dữ liệu <a class="header-anchor" href="#cau-4-trung-binh-phan-tich-qua-trinh-gui-du-lieu" aria-label="Permalink to &quot;Câu 4 (Trung bình): Phân tích quá trình gửi dữ liệu&quot;">​</a></h3><blockquote><p>Khi bạn mở trang <code>https://google.com</code>, dữ liệu request đi qua 7 tầng OSI như thế nào? Hãy mô tả ngắn gọn hành động tại tầng 7, 4, 3, và 2.</p></blockquote><p><strong>Đáp án:</strong></p><ul><li><strong>Tầng 7 (Application):</strong> Trình duyệt tạo HTTP GET request, dùng giao thức HTTPS.</li><li><strong>Tầng 4 (Transport):</strong> TCP tạo segment, gắn port nguồn (ngẫu nhiên) và port đích (443 – HTTPS).</li><li><strong>Tầng 3 (Network):</strong> IP đóng gói segment thành packet, gắn IP nguồn (IP máy bạn) và IP đích (IP của Google).</li><li><strong>Tầng 2 (Data Link):</strong> Gắn địa chỉ MAC nguồn (card mạng của bạn) và MAC đích (router). Tạo Frame để truyền trong LAN.</li></ul><hr><h3 id="cau-5-van-dung-tinh-huong-thuc-te" tabindex="-1">Câu 5 (Vận dụng): Tình huống thực tế <a class="header-anchor" href="#cau-5-van-dung-tinh-huong-thuc-te" aria-label="Permalink to &quot;Câu 5 (Vận dụng): Tình huống thực tế&quot;">​</a></h3><blockquote><p>Kỹ thuật viên phát hiện máy tính không thể kết nối Internet nhưng vẫn ping được máy tính khác trong cùng mạng LAN. Vấn đề nằm ở tầng OSI nào? Giải thích.</p></blockquote><p><strong>Đáp án:</strong> Vấn đề nằm ở <strong>Tầng 3 (Network Layer)</strong> trở lên.</p><p><strong>Giải thích:</strong></p><ul><li>Máy tính vẫn ping được trong LAN → Tầng 1 (Physical), Tầng 2 (Data Link) hoạt động bình thường – cáp tốt, switch tốt, địa chỉ MAC nhận diện được.</li><li>Không ra được Internet → Có thể lỗi ở Tầng 3: địa chỉ IP sai, subnet mask sai, gateway mặc định (router) chưa được cấu hình, hoặc router gặp sự cố.</li><li>Cần kiểm tra: địa chỉ IP, subnet mask, default gateway bằng lệnh <code>ipconfig</code> (Windows).</li></ul><hr><h2 id="🔹-9-loi-thuong-gap" tabindex="-1">🔹 9. LỖI THƯỜNG GẶP <a class="header-anchor" href="#🔹-9-loi-thuong-gap" aria-label="Permalink to &quot;🔹 9. LỖI THƯỜNG GẶP&quot;">​</a></h2><h3 id="❌-loi-1-nham-so-tang-va-ten-tang" tabindex="-1">❌ Lỗi 1: Nhầm số tầng và tên tầng <a class="header-anchor" href="#❌-loi-1-nham-so-tang-va-ten-tang" aria-label="Permalink to &quot;❌ Lỗi 1: Nhầm số tầng và tên tầng&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Tầng 1 là Application, Tầng 7 là Physical.&quot;</p><p><strong>Đúng:</strong> Ngược lại – <strong>Tầng 1 là Physical</strong> (vật lý, thấp nhất), <strong>Tầng 7 là Application</strong> (ứng dụng, cao nhất). Nhớ: số tầng <strong>tăng dần từ dưới lên</strong> (từ phần cứng đến phần mềm).</p><hr><h3 id="❌-loi-2-nham-router-va-switch-voi-tang-osi" tabindex="-1">❌ Lỗi 2: Nhầm Router và Switch với tầng OSI <a class="header-anchor" href="#❌-loi-2-nham-router-va-switch-voi-tang-osi" aria-label="Permalink to &quot;❌ Lỗi 2: Nhầm Router và Switch với tầng OSI&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Switch hoạt động ở Tầng 3, Router ở Tầng 2.&quot;</p><p><strong>Đúng:</strong> <strong>Switch</strong> ở <strong>Tầng 2</strong> (dùng MAC address), <strong>Router</strong> ở <strong>Tầng 3</strong> (dùng IP address). Dùng mẹo: R(outer) → R(outing) → R(3ầng 3).</p><hr><h3 id="❌-loi-3-nham-đon-vi-du-lieu" tabindex="-1">❌ Lỗi 3: Nhầm đơn vị dữ liệu <a class="header-anchor" href="#❌-loi-3-nham-đon-vi-du-lieu" aria-label="Permalink to &quot;❌ Lỗi 3: Nhầm đơn vị dữ liệu&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Gói tin (packet) được tạo ra ở Tầng 2.&quot;</p><p><strong>Đúng:</strong> <strong>Packet</strong> được tạo ở <strong>Tầng 3 (Network)</strong>. Tầng 2 tạo <strong>Frame</strong>, Tầng 4 tạo <strong>Segment</strong>, Tầng 1 truyền <strong>Bit</strong>. Nhớ: <strong>P</strong>acket = <strong>P</strong>hần 3 (tầng 3).</p><hr><h3 id="❌-loi-4-nghi-osi-va-tcp-ip-la-giong-nhau-hoan-toan" tabindex="-1">❌ Lỗi 4: Nghĩ OSI và TCP/IP là giống nhau hoàn toàn <a class="header-anchor" href="#❌-loi-4-nghi-osi-va-tcp-ip-la-giong-nhau-hoan-toan" aria-label="Permalink to &quot;❌ Lỗi 4: Nghĩ OSI và TCP/IP là giống nhau hoàn toàn&quot;">​</a></h3><p><strong>Sai:</strong> &quot;TCP/IP cũng có 7 tầng như OSI.&quot;</p><p><strong>Đúng:</strong> TCP/IP chỉ có <strong>4 tầng</strong>. Nó gộp tầng 7+6+5 thành <strong>Application</strong>, gộp tầng 2+1 thành <strong>Network Access</strong>. OSI là mô hình lý thuyết, TCP/IP là mô hình thực tế được dùng trên Internet ngày nay.</p><hr><h3 id="❌-loi-5-nghi-phan-mem-nhu-chrome-word-la-tang-7" tabindex="-1">❌ Lỗi 5: Nghĩ phần mềm như Chrome, Word là &quot;Tầng 7&quot; <a class="header-anchor" href="#❌-loi-5-nghi-phan-mem-nhu-chrome-word-la-tang-7" aria-label="Permalink to &quot;❌ Lỗi 5: Nghĩ phần mềm như Chrome, Word là &quot;Tầng 7&quot;&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Chrome là ứng dụng nên nó là Tầng 7 của OSI.&quot;</p><p><strong>Đúng:</strong> Chrome (trình duyệt) là <strong>phần mềm người dùng</strong>, không phải Tầng 7. Tầng 7 (Application Layer) là các <strong>giao thức mạng</strong> mà Chrome sử dụng – cụ thể là <strong>HTTP/HTTPS</strong>. Tầng 7 không phải là ứng dụng, mà là giao thức mà ứng dụng dùng để giao tiếp qua mạng.</p>`,115)])])}const p=n(h,[["render",g]]);export{u as __pageData,p as default};
